import os
import requests
from datetime import datetime, timedelta

# Using Auth0 as the third-party managed service
AUTH0_DOMAIN = os.getenv('AUTH0_DOMAIN')
AUTH0_CLIENT_ID = os.getenv('AUTH0_CLIENT_ID')
AUTH0_CLIENT_SECRET = os.getenv('AUTH0_CLIENT_SECRET')

def refresh_auth0_token(refresh_token):
    """
    Refresh an expired Auth0 access token using refresh token
    """
    url = f"https://{AUTH0_DOMAIN}/oauth/token"

    payload = {
        "grant_type": "refresh_token",
        "client_id": AUTH0_CLIENT_ID,
        "client_secret": AUTH0_CLIENT_SECRET,
        "refresh_token": refresh_token
    }

    headers = {
        "Content-Type": "application/json"
    }

    response = requests.post(url, json=payload, headers=headers)

    if response.status_code == 200:
        token_data = response.json()
        return {
            "access_token": token_data["access_token"],
            "expires_in": token_data["expires_in"],
            "token_type": token_data["token_type"],
            "refresh_token": token_data.get("refresh_token", refresh_token)
        }
    else:
        raise Exception(f"Failed to refresh token: {response.text}")

def is_token_expired(expiry_time):
    """Check if token has expired"""
    return datetime.now() >= expiry_time

def refresh_expired_session(current_refresh_token):
    """Main function to handle session refresh"""
    try:
        # Attempt to refresh the token
        refreshed_tokens = refresh_auth0_token(current_refresh_token)

        # Calculate new expiration time (assuming expires_in is in seconds)
        expiry_time = datetime.now() + timedelta(seconds=refreshed_tokens["expires_in"])

        return {
            "success": True,
            "access_token": refreshed_tokens["access_token"],
            "expires_at": expiry_time,
            "refresh_token": refreshed_tokens["refresh_token"]
        }
    except Exception as e:
        return {
            "success": False,
            "error": str(e)
        }
